"""Install account-scoped discretion controls for chat and the Codex workspace."""

import argparse
import base64
import gzip
import json
import os
import runpy
import sys
import tempfile
from pathlib import Path

PAYLOAD = ''  # noqa: E501 - reviewed discretion setup


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    root = Path(tempfile.mkdtemp(prefix="dhanz-autonomy-setup-", dir=Path.home()))
    root.chmod(0o700)
    files = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    for name, source in files.items():
        (root / name).write_text(source)
        (root / name).chmod(0o600)
    sys.path.insert(0, str(root))
    from web_release import fetch_release, version_key

    release = fetch_release()
    if version_key(release["version"], release["build"]) < version_key("0.10.5", 43):
        raise ValueError("The checked autonomy browser build is not published yet. Nothing changed.")
    # Validate/stage the actual Caddy browser mount and package before restarting API.
    sys.argv = [str(root / "apply_web_release.py")]
    runpy.run_path(sys.argv[0], run_name="__main__")
    sys.argv = [str(root / "install_autonomy_backend.py")] + (["--apply"] if args.apply else [])
    runpy.run_path(sys.argv[0], run_name="__main__")
    if args.apply:
        sys.argv = [str(root / "enable_autonomy_setting.py"), "--apply"]
        runpy.run_path(sys.argv[0], run_name="__main__")
        sys.argv = [str(root / "apply_web_release.py"), "--apply"]
        runpy.run_path(sys.argv[0], run_name="__main__")
        print("Use discretion controls installed. Refresh Edge with Ctrl+F5; close and reopen the Android web app.")
        print("Use the sparkle button above chat or Chat with Codex to turn discretion on or off for your account.")
        print("Routine decisions proceed automatically; existing permissions and bounded model usage still apply.")


if __name__ == "__main__":
    os.umask(0o077)
    try:
        main()
    except (ValueError, OSError) as exc:
        raise SystemExit(str(exc)) from None
